					<circle class="pulse 12" style="animation-delay: 1.4s; display: none;" cx="844" cy="412" r="4"></circle>
					<circle class="fill-[#e71143]" cx="844" cy="412" r="4" style="display: none;"></circle>

					<circle class="pulse 13" style="animation-delay: 0.1s; display: inline;" cx="573" cy="373" r="4"></circle>
					<circle class="fill-[#e71143]" cx="573" cy="373" r="4" style="display: inline;"></circle>

					<circle class="pulse 14" style="animation-delay: 1.2s; display: inline;" cx="755" cy="130" r="4"></circle>
					<circle class="fill-[#e71143]" cx="755" cy="130" r="4" style="display: inline;"></circle>
				</g>


			</svg>
			<script>
	document.addEventListener("DOMContentLoaded", () => {
		const steps = [12, 24, 36];
		const directions = [
			[0, 1],  
			[0, -1],  
			[1, 0],   
			[-1, 0]   
		];

		const allCircles = document.querySelectorAll("g > circle");
		const circlePairs = [];
		for (let i = 0; i < allCircles.length; i += 2) {
			circlePairs.push([allCircles[i], allCircles[i + 1]]);
		}

		function getVisiblePairs() {
			return circlePairs.filter(([pulse]) => pulse.style.display !== "none");
		}

		function randomlyUpdatePoints() {
			const visiblePairs = getVisiblePairs();
			const total = circlePairs.length;

			const countToChange = Math.floor(Math.random() * 4) + 2;
			const shuffled = circlePairs.sort(() => Math.random() - 0.5).slice(0, countToChange);

			shuffled.forEach(([pulse, fill]) => {
				const isVisible = pulse.style.display !== "none";

				const action = Math.random();

				if (action < 0.5) {
					const cx = parseFloat(pulse.getAttribute("cx"));
					const cy = parseFloat(pulse.getAttribute("cy"));
					const dir = directions[Math.floor(Math.random() * directions.length)];
					const step = steps[Math.floor(Math.random() * steps.length)];
					const newCx = cx + dir[0] * step;
					const newCy = cy + dir[1] * step;
					pulse.setAttribute("cx", newCx);
					pulse.setAttribute("cy", newCy);
					fill.setAttribute("cx", newCx);
					fill.setAttribute("cy", newCy);
				} else {
					const currentlyVisible = getVisiblePairs().length;
					if (isVisible && currentlyVisible > 5) {
						pulse.style.display = "none";
						fill.style.display = "none";
					} else if (!isVisible && Math.random() < 0.7) {
						pulse.style.display = "inline";
						fill.style.display = "inline";
					}
				}
			});
		}

		// دالة لتحريك 50% من النقاط عند بداية الصفحة
		function randomizeInitialPositions() {
			const total = circlePairs.length;
			const countToMove = Math.floor(total / 2);

			const shuffled = [...circlePairs].sort(() => Math.random() - 0.5).slice(0, countToMove);

			shuffled.forEach(([pulse, fill]) => {
				const cx = parseFloat(pulse.getAttribute("cx"));
				const cy = parseFloat(pulse.getAttribute("cy"));
				const dir = directions[Math.floor(Math.random() * directions.length)];
				const step = steps[Math.floor(Math.random() * steps.length)];
				const newCx = cx + dir[0] * step;
				const newCy = cy + dir[1] * step;
				pulse.setAttribute("cx", newCx);
				pulse.setAttribute("cy", newCy);
				fill.setAttribute("cx", newCx);
				fill.setAttribute("cy", newCy);

				// تأكد إنها ظاهرة
				pulse.style.display = "inline";
				fill.style.display = "inline";
			});
		}

		// عند تحميل الصفحة
		randomizeInitialPositions(); // حرّك 50% من النقاط
		randomlyUpdatePoints();      // أول تحديث عشوائي
		setInterval(() => {
			randomlyUpdatePoints();
		}, Math.floor(Math.random() * 3000) + 2000);
	});
</script>
